# Inventors Ladder: Ancient and Medieval Inventors (course key invancient). Helpers come from scripts/inventors/build.py.
# Archimedes matches the Great Books rung gbgreeks.archimedes-works (life c. 287–212 BC; Heath 1897 translation).

LESSONS = {
 "archimedes": LES([
  P("Archimedes (c. 287–212 BC) lived in Syracuse, a rich Greek city on the island of Sicily. He wrote to the mathematicians of Alexandria in Egypt, and many of his books open with a friendly letter to one of them. He was a mathematician first, but the stories people told about him for centuries were about his machines: pulleys that let one man move a ship, and engines that defended Syracuse against the Roman army."),
  K("Archimedes turned questions about machines into questions of proof. Why does a lever work? Why do some things float? He answered with careful geometry, and his answers still hold: <b>a lever balances when weight times distance is the same on both sides</b>, and <b>a body in water is pushed up by the weight of the water it pushes aside</b>."),
  H("The problem"),
  P("Builders in Archimedes' time already used levers, pulleys and screws. They knew <i>that</i> they worked, from long practice. Nobody had shown <i>why</i>, or how to predict exactly what a machine would do before building it. Archimedes wanted rules as certain as Euclid's geometry."),
  H("How the idea came"),
  P("In <i>On the Equilibrium of Planes</i> he starts from a few simple claims anyone would grant, like \"equal weights at equal distances balance.\" From those, step by step, he proves the law of the lever."),
  Q("Two magnitudes, whether commensurable or incommensurable, balance at distances reciprocally proportional to the magnitudes.",
    "Archimedes", "On the Equilibrium of Planes, Book I, Propositions 6 and 7", "Translated by T. L. Heath (Cambridge University Press, 1897)", "https://archive.org/details/worksofarchimede00arch"),
  P("\"Reciprocally proportional\" means the heavier weight sits closer to the pivot, in the same ratio. Twice the weight, half the distance. In modern words, $W_1 d_1 = W_2 d_2$."),
  V("iv-lever", {"mode": "lever"}, "Drag the weights along the beam, or change them with the sliders. The beam balances when weight times distance is the same on both sides."),
  EX("Balance the beam", "A 6 kg stone sits 2 m from the pivot. How far from the pivot must a 3 kg stone sit on the other side to balance it?",
     ["Weight times distance must match: $6 \\times 2 = 3 \\times d$.", "$12 = 3d$, so $d = 4$ m."], "4 m: half the weight needs twice the distance."),
  P("Plutarch, writing about 300 years later, says Archimedes told King Hiero that with enough force any weight could be moved, and showed it by pulling a loaded ship ashore with a set of pulleys, by himself. A later saying gives him the words \"give me a place to stand and I will move the Earth.\" The exact words are not in his own books, but the idea is his law of the lever."),
  H("Why things float"),
  P("In <i>On Floating Bodies</i> he proved what happens to a solid put in water."),
  Q("A solid heavier than a fluid will, if placed in it, descend to the bottom of the fluid, and the solid will, when weighed in the fluid, be lighter than its true weight by the weight of the fluid displaced.",
    "Archimedes", "On Floating Bodies, Book I, Proposition 7", "Translated by T. L. Heath (Cambridge University Press, 1897)", "https://archive.org/details/worksofarchimede00arch"),
  V("iv-lever", {"mode": "float"}, "Choose a material and lower the block into water. The scale shows how much lighter it gets: the weight of the water pushed aside."),
  EX("Weighed in water", "A metal block weighs 50 newtons in air and 30 newtons when hung in water. How much water does it push aside, by weight?",
     ["It lost $50 - 30 = 20$ N of weight.", "By Archimedes' rule, that loss is the weight of the water displaced."], "20 newtons of water, about 2 liters."),
  H("The crown: what we know and what is a story"),
  P("The most famous Archimedes story is told by the Roman architect Vitruvius, about two hundred years after Archimedes died. King Hiero gave a goldsmith gold for a crown, then heard that some gold had been swapped for silver. Here is how Vitruvius tells what happened next."),
  Q("The latter, while the case was still on his mind, happened to go to the bath, and on getting into a tub observed that the more his body sank into it the more water ran out over the tub. As this pointed out the way to explain the case in question, without a moment's delay, and transported with joy, he jumped out of the tub and rushed home naked, crying with a loud voice that he had found what he was seeking; for as he ran he shouted repeatedly in Greek, \"Eureka, eureka.\"",
    "Vitruvius", "The Ten Books on Architecture, Book IX, Introduction", "Translated by Morris Hicky Morgan (Harvard University Press, 1914)", "https://archive.org/details/thetenbooksonarc20239gut", "The Greek word is printed in Latin letters here."),
  P("In Vitruvius' version, Archimedes dropped the crown, a lump of pure gold of the same weight, and a lump of silver of the same weight into a brimming vessel, and measured the water that spilled. Silver is less dense than gold, so the same weight of silver takes up more room. The crown spilled more water than the gold lump, so it held some silver."),
  LEGEND("<p>The bath and the run through the streets are a <b>legend</b>: no writing by Archimedes mentions a crown, and Vitruvius lived two centuries later. Many historians also doubt the spill method as told, because the difference in spilled water would have been tiny for a crown. Some suggest Archimedes would rather have weighed the crown against gold while both hung in water, using his own law of floating bodies. The idea, that a mixture of metals takes up a different volume than pure gold of the same weight, is sound.</p>"),
  H("Machines of war, and the end"),
  P("When Roman forces under Marcellus attacked Syracuse during the Second Punic War, ancient writers say Archimedes' catapults and cranes held them off for a long time. Polybius, Livy and Plutarch all describe the machines. The story that he set ships on fire with mirrors appears only in much later writers, and modern tests have not settled whether it could work; treat it as a legend. Syracuse fell in 212 BC, and Archimedes was killed by a Roman soldier. Plutarch gives several versions of how it happened and says Marcellus was grieved by it."),
  TL([
   ("c. 287 BC", "Born in Syracuse, Sicily"),
   ("3rd century BC", "Writes On the Equilibrium of Planes, On Floating Bodies, Measurement of a Circle, The Sand-Reckoner and other works"),
   ("214–212 BC", "Roman siege of Syracuse; his machines help defend the city"),
   ("212 BC", "Syracuse is taken; Archimedes is killed"),
   ("c. 20 BC", "Vitruvius tells the story of the crown and \"Eureka\""),
   ("75 BC", "Cicero, in Sicily, finds Archimedes' overgrown tomb, marked with a sphere and a cylinder"),
  ], "Timeline (dates BC count down: 212 BC is 75 years before 137 BC)"),
  EX("Counting years across BC", "How many years passed between Archimedes' death (212 BC) and Cicero finding his tomb (75 BC)?",
     ["Both years are BC, so the later year is the smaller number.", "$212 - 75 = 137$ years."], "137 years."),
  H("What it led to"),
  P("Archimedes' law of the lever is the start of the science of statics, which every bridge and crane designer uses. His rule for floating bodies explains why a steel ship floats: its hollow shape pushes aside a great deal of water. Galileo, eighteen centuries later, admired him above all the ancient writers and built on his methods."),
  M("Thinking a long lever makes force for free. A lever trades distance for force: to lift a heavy load a little way, you push a small force a long way. The work in and out stays the same."),
  GB([("/great-books/the-greeks/archimedes-works/", "Archimedes: The Works", "read the lever and floating-body proofs in Heath's translation")]),
  TRYIT([("lemon-battery", "Not ready for electricity yet? Start the From Scratch course with a battery made of lemons.")]),
  P("Read more: " + GK("Archimedes") + "."),
  TRY,
 ], "heath", "vitruvius", "plutarch_marc", "g_archimedes"),

 "hero-of-alexandria": LES([
  P("Hero (or Heron) of Alexandria worked in the great city of Roman Egypt. Scholars date him to the first century AD, partly because he describes an eclipse of the Moon that matches one in AD 62. Almost nothing is known about his life. What survives are his books: on air and water (<i>Pneumatics</i>), on automatic theaters (<i>Automata</i>), on measuring land (<i>Metrica</i> and <i>Dioptra</i>), on mirrors and on war machines. Many seem to be teaching books, written for students."),
  K("Hero collected and invented machines that ran on <b>air pressure, water and steam</b>. His most famous, the aeolipile, spun because steam rushing out of bent nozzles pushed it the other way: the same action and reaction that drives a rocket."),
  H("The problem"),
  P("Alexandria's teachers wanted to show that air is real stuff that takes up space and can push. Temples and wealthy owners also liked marvels: doors that opened by themselves, statues that poured wine, birds that sang. Hero's books show how to build both kinds of thing."),
  H("The spinning steam ball"),
  Q("Place a cauldron over a fire: a ball shall revolve on a pivot.",
    "Hero of Alexandria", "Pneumatics, section 50 (\"The Steam-Engine\")", "Translated by J. G. Greenwood, edited by Bennet Woodcroft (London, 1851)", "https://areeweb.polito.it/strutture/cemed/SUST_didattica.bk/2003/2003_Storia%20della%20tecnologia/WEB%20Materials%20&%20Sources/Steam_Library/hero/section50.html"),
  P("Water boils in a closed pot. The steam rises through a tube into a hollow ball that can turn. Two bent pipes stick out of the ball on opposite sides, pointing opposite ways. Steam jets out of each pipe, and the ball spins the other way."),
  V("iv-aeolipile", None, "Turn up the heat. More steam leaves the nozzles faster, and the push back on the ball spins it faster. Friction at the pivot slows it."),
  W("Steam leaving a nozzle is pushed one way, so it pushes the nozzle the other way, equally hard. With two nozzles pointing opposite ways around the ball, both pushes turn it the same direction. Newton stated this rule 1,600 years later as his third law."),
  LEGEND("<p>The aeolipile is often called the first steam engine, and people ask why the Romans did not start an industrial revolution. Be careful: Hero describes it as a <b>demonstration</b>. It did no useful work, and a spinning ball with open jets wastes almost all its steam. Historians give many reasons for the gap, from the cost of fuel and metalworking to the economics of the time. None is proven, so it is a question to think about, not a fact to learn.</p>"),
  H("Automatic doors and a coin machine"),
  P("In other sections Hero shows how a fire on an altar could open temple doors by itself: heated air pushes water from one vessel into a bucket, the bucket gets heavy and pulls ropes that turn the door posts. When the fire dies, the air cools and the doors close. He also describes a vessel that pours out a little holy water when a coin is dropped in: the coin lands on a small pan, tips a lever and opens a valve until the coin slides off. It is often called the first vending machine."),
  P("In the <i>Dioptra</i> he describes an odometer for a cart: gears count the turns of a wheel and move a pointer that shows the distance. The Roman writer Vitruvius describes a similar machine that drops a pebble into a box at the end of every mile, so a surveyor could count pebbles instead of pacing."),
  EX("A pebble odometer", "A cart wheel goes 4 meters each time it turns. Gears drop one pebble every 400 turns. How far has the cart gone when there are 9 pebbles in the box?",
     ["One pebble means $400 \\times 4 = 1600$ m.", "Nine pebbles: $9 \\times 1600 = 14{,}400$ m, or 14.4 km."], "14,400 meters."),
  H("What he tried, and what we can't know"),
  P("We don't know how many of Hero's devices he built himself, and which he copied from earlier inventors such as Ctesibius, the Alexandrian engineer who made pumps and water clocks a few centuries before him. Hero openly says he is building on others' work and adding his own. That is how most invention happens."),
  TL([
   ("3rd century BC", "Ctesibius in Alexandria builds pumps, water organs and water clocks"),
   ("c. AD 10–70", "Hero's likely lifetime (the dates are uncertain)"),
   ("AD 62", "An eclipse of the Moon that Hero describes in his Dioptra"),
   ("1575", "Hero's Pneumatics printed in a Latin translation, read by Renaissance engineers"),
   ("1851", "Bennet Woodcroft publishes an English translation of the Pneumatics"),
  ]),
  EX("How long ago?", "Hero described an eclipse in AD 62. How many years before AD 2000 was that?",
     ["Both years are AD, so subtract.", "$2000 - 62 = 1938$ years."], "1,938 years."),
  H("What it led to"),
  P("Renaissance engineers read Hero in print and built his devices again. His idea that air and steam can push was the seed of later work on air pumps and pressure. Today's jet engines and rockets turn on the same idea as his spinning ball."),
  M("Saying Hero invented the steam engine that powered factories. That engine, with a piston, came in the 1700s with Newcomen and James Watt. Hero's ball shows the push of steam, but it did no work."),
  TRYIT([("simple-motor", "Build a simple motor that spins from a battery, the electric cousin of Hero's spinning ball")]),
  P("Read more: " + GK("Hero_of_Alexandria", "Hero of Alexandria") + " and " + GK("Aeolipile") + "."),
  TRY,
 ], "woodcroft", "g_hero"),

 "ibn-al-haytham": LES([
  P("Abu Ali al-Hasan ibn al-Haytham (c. AD 965–c. 1040), known in Latin Europe as Alhazen, was born in Basra, in today's Iraq, and did most of his known work in Cairo. He wrote on mathematics, astronomy and optics. His <i>Book of Optics</i> (in Arabic, <i>Kitab al-Manazir</i>), written in the early 1000s, changed how people understood light and sight."),
  K("Ibn al-Haytham showed that <b>we see because light travels from objects into our eyes</b>, in straight lines, and he backed his claims with <b>experiments anyone could repeat</b>, such as light passing through a small hole into a dark room."),
  H("The problem"),
  P("How do we see? Some ancient thinkers, such as Euclid and Ptolemy, said the eye sends out rays that touch things, like feeling with a stick. Others, following Aristotle, said objects send something to the eye. Each side had arguments. Ibn al-Haytham asked which idea fits what we can test."),
  H("How the idea came"),
  P("He pointed out that looking at the Sun hurts the eye, and a bright light leaves an afterimage. Something is coming <i>in</i>. And when you open your eyes at night, you see distant stars at once: could rays from the eye really reach them that fast? He then built a full theory: every point of a lit object sends light out in all directions, in straight lines, and the eye collects it."),
  H("The dark room experiment"),
  P("He described setting several lamps outside a room with a small hole in its wall. Each lamp made its own spot of light on the wall inside. Cover one lamp and its spot goes dark, and only that one. So light from each lamp travels in its own straight line through the hole, and the lines cross without mixing. Later scientists called a darkened room with a hole a <i>camera obscura</i>, Latin for \"dark room.\""),
  V("iv-camera", None, "Rays from the top of the tree pass through the hole and land low on the back wall; rays from the bottom land high. The picture is upside down. Drag the tree or change the hole size and depth."),
  W("Light goes in straight lines. A ray from the top of the object must go down through the hole and keep going down, so it lands at the bottom of the screen. The bigger the hole, the more each point spreads into a blur; the smaller, the sharper but dimmer the image."),
  EX("How big is the image?", "A tree 6 m tall stands 20 m from a pinhole. The back wall is 0.5 m behind the hole. How tall is the upside-down image?",
     ["The two triangles, tree to hole and hole to wall, have the same shape.", "$\\dfrac{h}{6} = \\dfrac{0.5}{20}$, so $h = 6 \\times 0.025 = 0.15$ m."], "0.15 m, or 15 cm, upside down."),
  H("Testing, not just arguing"),
  P("What makes him stand out is his method. He tested claims with set-ups he described carefully, so others could repeat them, and he checked his ideas against measurements. He also wrote a book of <i>Doubts Concerning Ptolemy</i>, listing places where the great astronomer's work did not hold together. Many historians count him among the founders of experimental science; others point out that experiment had older roots too. Both agree his optics was a big step."),
  N("We don't quote Ibn al-Haytham here because the standard English translations of his books are recent and still under copyright. Everything above is in our own words."),
  LEGEND("<p>A popular story says Ibn al-Haytham pretended to be mad to escape an impossible job: the Caliph al-Hakim had asked him to control the Nile's floods, and he saw it couldn't be done. The story comes from biographers writing after his death, and historians treat it with caution.</p>"),
  TL([
   ("c. AD 965", "Born in Basra"),
   ("early 1000s", "Moves to Cairo under the Fatimid caliphs"),
   ("c. 1011–1021", "Writes the Book of Optics (the dates are approximate)"),
   ("c. 1040", "Dies in Cairo"),
   ("c. 1200", "The Book of Optics is translated into Latin as De aspectibus"),
   ("1572", "Printed in Basel; read by Kepler and others"),
  ]),
  EX("A long road to print", "The Book of Optics was finished around 1021 and printed in 1572. About how many years passed?",
     ["$1572 - 1021 = 551$."], "About 550 years."),
  H("What it led to"),
  P("Latin scholars such as Roger Bacon and Witelo built on his optics. Kepler, around 1604, used his ideas to explain how the lens of the eye forms an upside-down picture on the retina. Leonardo da Vinci compared the eye to a dark room with a hole, and the camera obscura became a tool for artists and the ancestor of the photographic camera."),
  M("Thinking the hole makes the image upside down by some trick of the hole. Nothing flips: the rays simply keep going straight, so top and bottom cross at the hole."),
  TRYIT([("crystal-radio", "Light is one kind of wave; build a crystal radio to catch another")]),
  P("Read more: " + GK("Ibn_al-Haytham", "Ibn al-Haytham") + ", " + GK("Book_of_Optics", "Book of Optics") + " and " + GK("Camera_obscura", "Camera obscura") + "."),
  TRY,
 ], "g_haytham", "g_camera", "sabra"),
}
